# CoreDNS 监控配置
apiVersion: monitoring.coreos.com/v1
kind: ServiceMonitor
metadata:
  name: coredns
  namespace: monitoring
  labels:
    app: coredns
spec:
  jobLabel: k8s-app
  selector:
    matchLabels:
      k8s-app: kube-dns
  namespaceSelector:
    matchNames:
    - kube-system
  endpoints:
  - port: metrics
    interval: 30s
    path: /metrics
    relabelings:
    - sourceLabels: [__meta_kubernetes_pod_name]
      targetLabel: pod
    - sourceLabels: [__meta_kubernetes_namespace]
      targetLabel: namespace

---
# CoreDNS Grafana Dashboard
apiVersion: v1
kind: ConfigMap
metadata:
  name: coredns-dashboard
  namespace: monitoring
data:
  coredns-dashboard.json: |
    {
      "dashboard": {
        "title": "CoreDNS Monitoring",
        "panels": [
          {
            "title": "DNS 查询率",
            "type": "graph",
            "targets": [
              {
                "expr": "rate(coredns_dns_requests_total[5m])",
                "legendFormat": "{{type}}"
              }
            ]
          },
          {
            "title": "DNS 响应时间 P99",
            "type": "graph",
            "targets": [
              {
                "expr": "histogram_quantile(0.99, sum(rate(coredns_dns_request_duration_seconds_bucket[5m])) by (le))",
                "legendFormat": "P99 延迟"
              }
            ]
          },
          {
            "title": "缓存命中率",
            "type": "graph",
            "targets": [
              {
                "expr": "rate(coredns_cache_hits_total[5m]) / (rate(coredns_cache_hits_total[5m]) + rate(coredns_cache_misses_total[5m]))",
                "legendFormat": "缓存命中率"
              }
            ]
          },
          {
            "title": "错误率",
            "type": "graph",
            "targets": [
              {
                "expr": "rate(coredns_dns_responses_total{rcode!=\"NOERROR\"}[5m])",
                "legendFormat": "{{rcode}}"
              }
            ]
          }
        ]
      }
    }

# 多集群 DNS 联邦配置
apiVersion: v1
kind: ConfigMap
metadata:
  name: multicloud-dns
  namespace: kube-system
data:
  Corefile: |
    # 本地集群配置
    .:53 {
        errors
        health
        kubernetes cluster.local in-addr.arpa ip6.arpa {
            pods insecure
            fallthrough in-addr.arpa ip6.arpa
        }
        prometheus :9153
        forward . /etc/resolv.conf
        cache 30
        loop
        reload
        loadbalance
    }

    # 远程集群联邦配置
    cluster-east.example.com:53 {
        errors
        cache 300
        forward . 10.10.0.10 10.10.0.11 {
            health_check 5s
        }
    }

    cluster-west.example.com:53 {
        errors
        cache 300
        forward . 10.20.0.10 10.20.0.11 {
            health_check 5s
        }
    }
